def remember_watch_start_batch(targets_info)
  count = targets_info.respond_to?(:size) ? targets_info.size : 0
  @watch_rt[:last_start_batch] = count
  @watch_rt_gen += 1
  count
end

def remember_watch_stop_batch(targets_info)
  count = targets_info.respond_to?(:size) ? targets_info.size : 0
  @watch_rt[:last_stop_batch] = count
  @watch_rt_gen += 1
